import pytest
from pydantic import ValidationError

from reviewlens.rules import fallback_reply, forced_high_urgency, mask_pii, reply_problems
from reviewlens.sanitize import find_banned_ui_words, output_problems
from reviewlens.schema import ReviewAnalysis


@pytest.mark.parametrize(
    "text",
    [
        "As an AI, I cannot taste food.",
        "I am an assistant for the restaurant.",
        "This reply was generated by ChatGPT.",
        "Sorry, as a language model I can't help.",
        "Certainly! We are sorry.",
        "We will leverage your feedback.",
        "Here's what we will do.",
    ],
)
def test_bad_output_detected(text):
    assert output_problems(text)


def test_clean_output_passes():
    assert output_problems("We are really sorry your order reached late and cold.") == []


def test_schema_rejects_self_reference_in_reply():
    with pytest.raises(ValidationError):
        ReviewAnalysis(
            sentiment="negative",
            category="delivery",
            urgency="high",
            language="English",
            summary="Order arrived late.",
            suggested_reply="As an AI assistant, I apologise.",
        )


def test_schema_rejects_multi_sentence_summary():
    with pytest.raises(ValidationError):
        ReviewAnalysis(
            sentiment="negative",
            category="delivery",
            urgency="high",
            language="English",
            summary="Order was late. Food was cold.",
            suggested_reply="Sorry about this.",
        )


def test_ui_words_detected():
    assert find_banned_ui_words("Smart insights powered by AI")
    assert find_banned_ui_words("Report \u2728")
    assert find_banned_ui_words("Upload reviews") == []


@pytest.mark.parametrize(
    "text",
    [
        "Got food poisoning after eating here",
        "Found a hair in my biryani",
        "Cockroach in the parotta!!",
        "Saapadu saapta odane vaanthi vandhuchu",
        "biryani la mudi irundhuchu",
        "சாப்பாட்டில் பூச்சி இருந்தது",
        "I will take this to consumer court",
    ],
)
def test_safety_keywords_force_high(text):
    assert forced_high_urgency(text)


@pytest.mark.parametrize(
    "text",
    [
        "Biryani was amazing, packing also neat.",
        "Saapadu mudinjuthu, very tasty",
        "Sick of waiting? No, it came on time.",
        "Nice food court outlet",
    ],
)
def test_safety_keywords_no_false_positive(text):
    assert not forced_high_urgency(text)


@pytest.mark.parametrize(
    "reply",
    [
        "We will refund your money.",
        "Please accept a 20% discount on your next order.",
        "We will send Rs. 200 as compensation.",
        "We accept full responsibility for this.",
        "Call us at 98765 43210.",
        "Visit https://example.com for help.",
    ],
)
def test_unsafe_replies_flagged(reply):
    assert reply_problems(reply)


def test_support_contact_allowed():
    assert reply_problems("Write to care@spiceroute.example.", "care@spiceroute.example") == []


def test_fallback_reply_is_safe():
    for cat in ["delivery", "food_quality", "price", "staff", "packaging", "app"]:
        reply = fallback_reply(cat, "negative")
        assert reply_problems(reply) == [] and output_problems(reply) == []


def test_mask_pii():
    assert mask_pii("call 98765 43210 or a@b.com") == "call [phone] or [email]"


@pytest.mark.parametrize(
    "reply",
    [
        "We will process your refund today.",
        "Your refund has been initiated.",
        "We'll refund the full amount.",
        "You will get a full refund.",
    ],
)
def test_refund_promises_flagged(reply):
    assert reply_problems(reply)


def test_acknowledging_refund_request_allowed():
    reply = "We hear your refund request. Please DM us your order ID so our team can look into it."
    assert reply_problems(reply) == []
